// Money helpers. Amounts are integer cents.
export function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const rest = cents % 100;
  return `$${dollars}.${rest}`;
}

export function addTax(cents, rate) {
  return Math.round(cents * (1 + rate));
}
