import { addTax, formatCents } from './money.js';

export function total(lines, taxRate) {
  const sub = lines.reduce((s, l) => s + l.qty * l.unitCents, 0);
  return formatCents(addTax(sub, taxRate));
}

export function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const rest = cents % 100;
  return `$${dollars}.${String(rest).padStart(2, "0")}`;
}
